<section class="panel"><h2>Recorded payments</h2><p>These are company-recorded received payments, not online payment requests.</p><?php if(!$payments): ?><p>No payment records to show.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Booking</th><th>Service</th><th>Amount (PHP)</th><th>Reference</th><th>Date recorded</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><a href="<?= site_url('receipts/'.$p['id']) ?>">#<?= (int)$p['id'] ?></a></td><td><a href="<?= site_url('bookings/'.$p['booking_id']) ?>">#<?= (int)$p['booking_id'] ?></a></td><td><?= esc($p['service_name']) ?></td><td><?= number_format((float)$p['amount'],2) ?></td><td><?= esc($p['reference']) ?></td><td><?= esc($p['paid_at']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
